// rig_test stage-only observer. Runs one bounded catalogue operation per Unity frame.
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using UnityEngine;
using Extensions;
namespace PerformanceReview {
public class D1Runner:MonoBehaviour {
 public static D1Runner Instance; public string Root;
 object reader; Type type; bool running; int repeats,target,remaining; string[] selected=new string[0];
 long initialHeap; Func<long> allocated; readonly List<Row> rows=new List<Row>(65536);
 public struct Row {public int frame;public string phase;public double ms;public long bytes;public int retained,completed,backlog;}
 void Awake(){Instance=this;DontDestroyOnLoad(gameObject);type=typeof(PersistentCity.Runtime.PopulationRuntime).Assembly.GetType("PersistentCity.Runtime.RivalFoodCatalogue");var m=typeof(GC).GetMethod("GetAllocatedBytesForCurrentThread",Type.EmptyTypes);if(m!=null)allocated=(Func<long>)Delegate.CreateDelegate(typeof(Func<long>),m);}
 object Invoke(string method,params object[] args)=>type.GetMethod(method).Invoke(reader,args);
 bool Pending=>(bool)type.GetProperty("RefreshPending").GetValue(reader);
 int Retained=>(int)type.GetProperty("RetainedPlaces").GetValue(reader);
 static string Place(BuildingRegistration r)=>"address:"+Uri.EscapeDataString(r.StreetName)+":"+r.StreetNumber+":shop";
 static bool Known(string n)=>n=="ba:itemname_croissant"||n=="ba:itemname_burger"||n=="ba:itemname_hotdog";
 static readonly JsonSerializerSettings Settings=new JsonSerializerSettings{ReferenceLoopHandling=ReferenceLoopHandling.Ignore,Converters={new Newtonsoft.Json.Converters.StringEnumConverter()}};
 static object Facts(CityBuildingController c){var r=c.buildingRegistration;return new{place=Place(r),street=r.StreetName,number=r.StreetNumber,creationDay=r.creationDay,businessType=r.businessTypeName,businessName=r.BusinessName,player=r.RentedByPlayer,owner=r.RentedByPlayer?"player":r.businessOwnerRivalId,established=r.HasEstablishedBusiness,available=r.AvailableForRent,temporaryClosure=r.temporarilyClosed,rating=r.satisfaction?.customerService,accessible=c.building.locatedInsidePrivateFenceIndex<0&&c.building.requiredDLC.DlcIsOwned(),door=c.entranceDoors!=null&&c.entranceDoors.Any(d=>d!=null&&d.doorTransform!=null),prices=r.retailPrices?.Where(p=>p!=null).Select(p=>new{product=p.itemName,price=p.price,bits=BitConverter.ToInt32(BitConverter.GetBytes(p.price),0)}).ToArray(),hours=r.scheduleDays?.Where(d=>d!=null&&d.isOpen&&d.openingHourSlots!=null).SelectMany(d=>d.openingHourSlots.Where(s=>s!=null).Select(s=>new{day=(int)d.day-1,from=s.startingHour*60,to=s.endingHour*60})).ToArray()};}
 static object Fields(object obj,int depth,HashSet<object> seen){if(obj==null)return null;var t=obj.GetType();if(t.IsPrimitive||t.IsEnum||obj is string||obj is decimal)return obj;if(obj is UnityEngine.Object u)return new{unityType=t.FullName,id=u==null?0:u.GetInstanceID()};if(depth<=0)return new{truncatedType=t.FullName};if(!t.IsValueType&&!seen.Add(obj))return new{cycle=t.FullName};try{if(obj is IDictionary dict){var d=new SortedDictionary<string,object>();foreach(DictionaryEntry e in dict)d[Convert.ToString(e.Key)]=Fields(e.Value,depth-1,seen);return d;}if(obj is IEnumerable seq){var list=new List<object>();foreach(var v in seq)list.Add(Fields(v,depth-1,seen));return list;}var fields=new SortedDictionary<string,object>();foreach(var f in t.GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)){if(f.IsStatic||typeof(Delegate).IsAssignableFrom(f.FieldType))continue;fields[f.Name]=Fields(f.GetValue(obj),depth-1,seen);}return fields;}finally{if(!t.IsValueType)seen.Remove(obj);}}
 object Native(){var all=CityManager.Instance.cityBuildingControllers.Where(c=>c!=null&&c.building!=null&&c.buildingRegistration!=null).ToArray();var food=all.Where(c=>c.buildingRegistration.HasEstablishedBusiness&&!c.buildingRegistration.AvailableForRent&&c.buildingRegistration.retailPrices!=null&&c.buildingRegistration.retailPrices.Any(p=>p!=null&&Known(p.itemName))).ToArray();var player=food.FirstOrDefault(c=>c.buildingRegistration.RentedByPlayer);var rival=food.FirstOrDefault(c=>!c.buildingRegistration.RentedByPlayer&&c.buildingRegistration.creationDay>=0&&!string.IsNullOrWhiteSpace(c.buildingRegistration.businessOwnerRivalId));var shortlist=new List<CityBuildingController>();if(rival!=null)shortlist.Add(rival);if(player!=null)shortlist.Add(player);foreach(var c in all.Where(c=>c.buildingRegistration.HasEstablishedBusiness&&!c.buildingRegistration.AvailableForRent&&c.buildingRegistration.creationDay>=0&&(c.buildingRegistration.RentedByPlayer||!string.IsNullOrWhiteSpace(c.buildingRegistration.businessOwnerRivalId)))){if(shortlist.Count>=8)break;if(!shortlist.Contains(c))shortlist.Add(c);}var requested=Path.Combine(Root,"shortlist.json");if(File.Exists(requested)){var wanted=JsonConvert.DeserializeObject<string[]>(File.ReadAllText(requested));shortlist=wanted.Select(p=>all.FirstOrDefault(c=>Place(c.buildingRegistration)==p)).ToList();if(shortlist.Any(c=>c==null))throw new Exception("Pinned native shortlist is missing a place");}selected=shortlist.Select(c=>Place(c.buildingRegistration)).Distinct().ToArray();return new{controllers=CityManager.Instance.cityBuildingControllers.Count(),registered=all.Length,foodShops=food.Length,eligibleRivalFood=food.Count(c=>!c.buildingRegistration.RentedByPlayer&&c.buildingRegistration.creationDay>=0&&!string.IsNullOrWhiteSpace(c.buildingRegistration.businessOwnerRivalId)),foodInventory=food.Select(Facts).ToArray(),rivalFood=food.Count(c=>!c.buildingRegistration.RentedByPlayer),playerFood=food.Count(c=>c.buildingRegistration.RentedByPlayer),selected,facts=shortlist.Select(Facts).ToArray(),rivalRegistration=rival==null?null:Fields(rival.buildingRegistration,14,new HashSet<object>()),saveFinanceFields=SaveGameManager.Current.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Where(f=>new[]{"rival","financ","money","bank","stock"}.Any(n=>f.Name.ToLowerInvariant().Contains(n))).ToDictionary(f=>f.Name,f=>Fields(f.GetValue(SaveGameManager.Current),14,new HashSet<object>()))};}
 public object Command(JObject q){string action=(string)q["action"];
  if(action=="native")return Native();
  if(action=="metadata")return new{available=type!=null,registrationFields=typeof(BuildingRegistration).GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Select(f=>new{name=f.Name,type=f.FieldType.FullName}).ToArray(),saveFields=SaveGameManager.Current.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Select(f=>new{name=f.Name,type=f.FieldType.FullName}).ToArray(),loaded=typeof(PersistentCity.Runtime.PopulationRuntime).Assembly.Location,moduleMvid=typeof(PersistentCity.Runtime.PopulationRuntime).Assembly.ManifestModule.ModuleVersionId.ToString(),loadedFileSha256=BitConverter.ToString(System.Security.Cryptography.SHA256.Create().ComputeHash(File.ReadAllBytes(typeof(PersistentCity.Runtime.PopulationRuntime).Assembly.Location))).Replace("-","").ToLowerInvariant()};
  if(type==null)return new{available=false};
  if(action=="arm"){running=false;if(reader!=null)Invoke("Dispose");reader=null;rows.Clear();repeats=0;needDump=false;target=(int?)q["repeats"]??int.MaxValue;initialHeap=GC.GetTotalMemory(true);reader=Activator.CreateInstance(type);return new{armed=true,initialHeap,selected};}
  if(action=="start"){running=true;return new{started=true,frame=Time.frameCount};}
  if(action=="stop"){running=false;string id=(string)q["id"];using(var w=new StreamWriter(Path.Combine(Root,"d1-"+id+".csv"))){w.WriteLine("frame,phase,ms,bytes,retained,completed,backlog");foreach(var row in rows)w.WriteLine(row.frame+","+row.phase+","+row.ms.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+row.bytes+","+row.retained+","+row.completed+","+row.backlog);}return new{repeats,units=rows.Count,running,retained=reader==null?0:Retained,initialHeap,heap=GC.GetTotalMemory(false),gc0=GC.CollectionCount(0),gc1=GC.CollectionCount(1),gc2=GC.CollectionCount(2),rowsFile="d1-"+id+".csv"};}
  if(action=="status")return new{repeats,running,units=rows.Count,retained=reader==null?0:Retained};
  if(action=="refusals"){var c=CityManager.Instance.cityBuildingControllers.FirstOrDefault(v=>v!=null&&v.buildingRegistration!=null&&v.buildingRegistration.HasEstablishedBusiness&&v.buildingRegistration.creationDay<0);return c==null?(object)new{available=false}:new{native=Facts(c),read=Invoke("ReadSelected",(object)new[]{Place(c.buildingRegistration)})};}
  if(action=="dump"){try{return new{refusedSession=false,read=Invoke("ReadSelected",(object)selected)};}catch(Exception e){return new{refusedSession=true,error=(e.InnerException??e).Message};}}
  if(action=="memory"){long before=GC.GetTotalMemory(true);int retained=Retained;Invoke("Dispose");reader=null;long after=GC.GetTotalMemory(true);return new{retained,before,after,releasedBytes=before-after,includesWeakHandles=false};}
  throw new Exception("Unknown D1 action");
 }
 void Update(){if(!running||reader==null)return;if(SaveGameManager.Current==null||!SaveGameManager.Current.SaveGameName.StartsWith("FT Food Routines")){running=false;return;}string phase="";long bytes=allocated==null?-1:allocated();long start=Stopwatch.GetTimestamp();try{if(!Pending){if(needDump){phase="dump8";Invoke("ReadSelected",(object)selected);needDump=false;repeats++;if(repeats>=target)running=false;}else{phase=repeats==0?"cold-begin":"warm-begin";Invoke("BeginRefresh");remaining=CityManager.Instance.cityBuildingControllers.Count();}}else{phase=repeats==0?"cold-unit16":"warm-unit16";if((bool)Invoke("ContinueRefresh",16)){needDump=true;remaining=0;}else remaining=Math.Max(0,remaining-16);}double ms=(Stopwatch.GetTimestamp()-start)*1000.0/Stopwatch.Frequency;long end=allocated==null?-1:allocated();rows.Add(new Row{frame=Time.frameCount,phase=phase,ms=ms,bytes=bytes<0?-1:end-bytes,retained=Retained,completed=repeats,backlog=remaining});}catch(Exception e){running=false;File.WriteAllText(Path.Combine(Root,"d1-error.json"),JsonConvert.SerializeObject(new{frame=Time.frameCount,phase,error=e.ToString()},Settings));}}
 bool needDump;
 public static object Dispatch(JObject q)=>Instance.Command(q);
}
}
